// Four facts, four owners — saying “Redux” for all four is the miss
export function Catalog({ searchParams }: { searchParams: { q?: string } }) {
  const q = searchParams.q ?? '' // URL owns the filter
  const { data: items } = useQuery({ queryKey: ['items', q], queryFn: () => api.items(q) })
  const [open, setOpen] = useState(false) // local UI: modal
  const qty = useCart((s) => s.items.length) // client graph: guest cart
  return (
    <>
      <p>Cart {qty}</p>
      <button onClick={() => setOpen(true)}>Filters</button>
      {open && <FilterSheet q={q} />}
      <ul>{items?.map((it) => <li key={it.id}>{it.title}</li>)}</ul>
    </>
  )
}
// Current user: httpOnly cookie + RSC. Theme: Context. Do not merge them here.

