// Cart in Context is the snippet they hand you. Catalog does not move.
// ❌ <Shop.Provider value={{ cart, setCart, items, setItems, draft }}> 
// ✅ catalog stays Query; cart moves to Zustand; draft stays local
export function Shop() {
  const { data: items } = useQuery({ queryKey: ['catalog'], queryFn: api.catalog })
  const add = useCart((s) => s.add)
  const [draft, setDraft] = useState('')
  return (
    <>
      <input value={draft} onChange={(e) => setDraft(e.target.value)} />
      <ul>{items?.map((it) => (
        <li key={it.id}><button onClick={() => add(it.id)}>{it.title}</button></li>
      ))}</ul>
    </>
  )
}

